{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_text",
        "budget_section_header_stack",
        "budget_table",
        "notes_h3",
        "notes_stack",
        "actions_h3",
        "actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Austin Individual Budget Plan: 2024 Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This budget framework provides a basic monthly financial plan for a single individual in Austin, Texas, with a net income of $4,000 USD, aiming to save 20% of their income. The plan allocates funds across common expense categories to help achieve financial goals while managing living costs in Austin.",
        "variant": "body"
      },
      "children": []
    },
    "budget_section_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "budget_icon",
        "budget_h3"
      ]
    },
    "budget_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000432_01_1_cash-stack.svg"
      },
      "children": []
    },
    "budget_h3": {
      "type": "Text",
      "props": {
        "text": "Monthly Budget Breakdown",
        "variant": "h3"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "amount",
            "label": "Monthly Amount (USD)"
          }
        ],
        "rows": [
          {
            "category": "Income (Net)",
            "amount": "$4,000"
          },
          {
            "category": "Savings Goal (20%)",
            "amount": "$800"
          },
          {
            "category": "Fixed Expenses:",
            "amount": ""
          },
          {
            "category": "Rent (1-bedroom apartment)",
            "amount": "$1,500"
          },
          {
            "category": "Utilities (Electricity, Water, Gas)",
            "amount": "$150"
          },
          {
            "category": "Internet",
            "amount": "$70"
          },
          {
            "category": "Phone Bill",
            "amount": "$60"
          },
          {
            "category": "Health Insurance (if not employer-covered)",
            "amount": "$100"
          },
          {
            "category": "Car Payment (if applicable)",
            "amount": "$300"
          },
          {
            "category": "Car Insurance",
            "amount": "$120"
          },
          {
            "category": "Variable Expenses:",
            "amount": ""
          },
          {
            "category": "Groceries",
            "amount": "$350"
          },
          {
            "category": "Dining Out / Takeaway",
            "amount": "$200"
          },
          {
            "category": "Transportation (Gas/Public Transit)",
            "amount": "$100"
          },
          {
            "category": "Personal Care / Health & Wellness",
            "amount": "$80"
          },
          {
            "category": "Entertainment / Hobbies",
            "amount": "$150"
          },
          {
            "category": "Clothing / Shopping",
            "amount": "$70"
          },
          {
            "category": "Miscellaneous / Buffer",
            "amount": "$100"
          },
          {
            "category": "Total Expenses",
            "amount": "$3,200"
          },
          {
            "category": "Remaining (Income - Savings - Expenses)",
            "amount": "$0"
          }
        ],
        "domain": "status",
        "preferredPresentation": "table",
        "numericColumns": [
          "amount"
        ]
      },
      "children": []
    },
    "notes_h3": {
      "type": "Text",
      "props": {
        "text": "Contextual Notes for Austin Living",
        "variant": "h3"
      },
      "children": []
    },
    "notes_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "note_housing",
        "note_utilities",
        "note_transportation",
        "note_savings",
        "note_flexibility"
      ]
    },
    "note_housing": {
      "type": "Text",
      "props": {
        "text": "Housing: Rent for a 1-bedroom apartment in Austin can vary significantly based on location and amenities. This budget uses an average estimate.",
        "variant": "body"
      },
      "children": []
    },
    "note_utilities": {
      "type": "Text",
      "props": {
        "text": "Utilities: Costs can fluctuate with seasonal weather, especially for air conditioning in summer.",
        "variant": "body"
      },
      "children": []
    },
    "note_transportation": {
      "type": "Text",
      "props": {
        "text": "Transportation: Austin is a car-centric city, but public transportation options are available. Ridesharing is also common.",
        "variant": "body"
      },
      "children": []
    },
    "note_savings": {
      "type": "Text",
      "props": {
        "text": "Savings: The 20% savings goal aligns with common financial advice for building wealth and emergency funds.",
        "variant": "body"
      },
      "children": []
    },
    "note_flexibility": {
      "type": "Text",
      "props": {
        "text": "Flexibility: This is a template; individual spending habits and priorities will require adjustments. Review and adapt monthly.",
        "variant": "body"
      },
      "children": []
    },
    "actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_budgeting_tools",
        "button_cost_of_living",
        "button_apartments"
      ]
    },
    "button_budgeting_tools": {
      "type": "Button",
      "props": {
        "label": "Explore Budgeting Tools"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nerdwallet.com/article/finance/best-budgeting-apps"
          }
        }
      },
      "children": []
    },
    "button_cost_of_living": {
      "type": "Button",
      "props": {
        "label": "Research Austin Cost of Living"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.numbeo.com/cost-of-living/in/Austin"
          }
        }
      },
      "children": []
    },
    "button_apartments": {
      "type": "Button",
      "props": {
        "label": "Find Apartments in Austin"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.apartments.com/austin-tx/"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_cost_of_living",
        "source_rent_data"
      ]
    },
    "source_cost_of_living": {
      "type": "Button",
      "props": {
        "label": "Cost of Living data (Austin, TX)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.numbeo.com/cost-of-living/in/Austin"
          }
        }
      },
      "children": []
    },
    "source_rent_data": {
      "type": "Button",
      "props": {
        "label": "Average Rent data (Austin, TX)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.rent.com/texas/austin-apartments/rent-trends"
          }
        }
      },
      "children": []
    }
  }
}
